function download(data:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function makeScenario(w:Workspace,purchase:Scenario['purchase']):Scenario{const start=today(),end=addDays(start,w.outlookDays);const events=w.events.flatMap(e=>{if(e.recurrence==='once')return e.date>=start&&e.date<=end?[{...e}]:[];if(!e.endDate||e.endDate<start||e.date>end)return [];let d=e.date;const step=e.recurrence==='weekly'?7:1;if(d<start)d=addDays(d,Math.ceil(days(d,start)/step)*step);return d<=end&&d<=e.endDate?[{...e,date:d,endDate:e.endDate<end?e.endDate:end}]:[]});return {startDate:start,horizonDate:end,balance:w.balance,reserve:w.reserve,purchase,events,origin:'manual',assumptions:[]}}
