function Empty({icon:Icon=Wallet,title,children,action}:{icon?:any;title:string;children:ReactNode;action?:ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={28}/></div><h3>{title}</h3><p>{children}</p>{action}</div>}
function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
